/* rvViagemJT: a programacao da JT/Mateus lida do print (mesmo formato da funcao ler-programacao-mateus) vira viagem do MESMO
   jeito do app (mtTentarAutomatico + mtGerarViagem): confere o peso com o cabecalho (mtConferir), escolhe o caminhao se nao
   vier placa (mtEscolherCaminhao), KM pelo roteiro (mtKmDaCarga), dias pelo historico da rota (mtDiasDaCarga), frete pela
   tabela da rota + adicional do periodo (freteRotaDe), paradas na ordem do roteiro (mateusParadas). */
function rvViagemJT(e) {
  e = e || {};
  var p = mtDaIA(e.leitura || {}), avisos = [];
  if (!p.cidades.length) return { ok: false, erro: "nao achei as cidades nessa programacao (mande o print inteiro, com volumes e peso)" };
  var c = mtConferir(p);
  if (c && c.bloqueia) return { ok: false, erro: "o PESO das cidades (" + c.somaPeso + " kg) nao fecha com o cabecalho (" + c.totalPeso + " kg). Peso errado vira frete errado -- confira o print", conferencia: c };
  if (c && !c.okVol) avisos.push("os volumes das cidades (" + c.somaVol + ") nao fecham com o cabecalho (" + c.totalVol + "), o peso fecha");
  if (c && !c.temTotais) avisos.push("o cabecalho nao veio no print, nao deu pra conferir a soma");
  var peso = 0, volumes = 0;
  p.cidades.forEach(function (x) { peso += Number(x.peso) || 0; volumes += Number(x.volumes) || 0; });
  var placa = String(e.placa || "").toUpperCase().replace(/[^A-Z0-9]/g, ""), esc = null;
  if (!placa) {
    esc = mtEscolherCaminhao(peso);
    if (!esc.placa) return { ok: false, erro: "nao escolhi caminhao: " + esc.motivo, ocupados: (esc.ocupados || []).map(function (o) { return o.v.placa + " (" + o.por + ")"; }) };
    placa = esc.placa;
  }
  var veic = (state.veiculos || []).find(function (x) { return String(x.placa || "").toUpperCase() === placa; });
  if (!veic) return { ok: false, erro: "a placa " + placa + " nao esta na frota cadastrada" };
  var data = e.data || rfDataLocalISO(new Date());
  var carga = String(p.carga || "");
  var jaTem = (state.viagens || []).find(function (x) { return x.placa === placa && x.data === data && String(x.cliente || "") === "JT/Mateus" && (carga ? String(x.cargaMateus || "") === carga : false); });
  if (jaTem) return { ok: false, erro: "a carga " + carga + " ja tem viagem lancada no " + placa + " em " + data, duplicada: jaTem.id };
  var outraCarga = carga ? (state.viagens || []).find(function (x) { return String(x.cargaMateus || "") === carga; }) : null;
  if (outraCarga) avisos.push("a carga " + carga + " ja aparece em outra viagem (" + outraCarga.placa + " de " + outraCarga.data + ")");
  var cap = (Number(veic.cargaUtilT) || 0) * 1000;
  if (cap > 0 && peso > cap) avisos.push("o peso (" + Math.round(peso) + " kg) passa da carga util do " + placa + " (" + cap + " kg)");
  var aberta = (state.viagens || []).find(function (x) { return x.placa === placa && !(Number(x.kmChegada) > 0) && /aguardando_motorista|em_andamento/.test(String(x.statusMotorista || "")); });
  if (aberta) avisos.push("o " + placa + " ja tem viagem aberta (" + aberta.cliente + " de " + aberta.data + ")");
  var rotaTar = mtCasarRotaTarifa(p.rota);
  var kmC = mtKmDaCarga(p);
  var dd = mtDiasDaCarga(p, 1);
  var valor = 0;
  try { if (rotaTar) valor = freteRotaDe("JT/Mateus", rotaTar, veic.tipo || "", peso, data) || 0; } catch (er) { valor = 0; }
  if (!valor && Number(e.frete) > 0) valor = Number(e.frete);
  if (!rotaTar) avisos.push("a rota " + p.rota + " nao esta na tabela da JT" + (valor ? ", usei o frete informado" : ", o frete ficou zerado"));
  var ordem = kmC.ordem || [], por = {};
  p.cidades.forEach(function (x) { por[x.nome] = x; });
  var trechos = {};
  (kmC.trechos || []).forEach(function (t) { if (!t.volta) trechos[t.para] = Math.round(t.km || 0); });
  var paradas = ordem.map(function (nome, i) { var x = por[nome] || {}; return { ordem: i + 1, cidade: nome, cod: x.cod, volumes: x.volumes, peso: x.peso, kmTrecho: trechos[nome] || 0 }; });
  p.cidades.forEach(function (x) { if (ordem.indexOf(x.nome) < 0) paradas.push({ ordem: paradas.length + 1, cidade: x.nome, cod: x.cod, volumes: x.volumes, peso: x.peso, kmTrecho: 0, semCoordenada: true }); });
  var v = {
    id: uid(), placa: placa, cliente: "JT/Mateus", rota: rotaTar || p.rota || "", data: data, criadoEm: Date.now(),
    dataCriacao: rfDataLocalISO(new Date()),
    valorViagem: valor, km: kmC.usado, dias: dd.dias,
    kmSaida: 0, kmChegada: 0, fotoKmSaida: "", fotoKmChegada: "", combustivelItens: [], outrosItens: [],
    vgPagMotorista: 500, vgPagAjudante: 300, temAjudante: true,
    motoristaNaEpoca: e.motorista || veic.motorista || "",
    pago: false, dataPagamento: "", pagoMotorista: false, dataPagamentoMotorista: "",
    pesoKg: Math.round(peso * 10) / 10,
    cargaMateus: carga, rotaCodMateus: String(p.rotaCod || ""),
    kmRetaMateus: kmC.reta, kmUrbanoMateus: kmC.urbano, kmOrdemMateus: ordem.join(" > "), mateusVolumes: volumes,
    mateusParadas: paradas, paradasFeitas: [],
    obs: "Programacao da Mateus" + (carga ? " (carga " + carga + ")" : "") + " criada pelo Ravi" + (e.pedidoPor ? " a pedido de " + e.pedidoPor : "") + " -- "
      + p.cidades.length + " cidade(s): " + (ordem.length ? ordem.join(" → ") : p.cidades.map(function (x) { return x.nome; }).join(", "))
      + ". KM " + (kmC.origem === "medido" ? "pela média medida em viagens anteriores desta rota" : "estimado pelo roteiro") + "."
      + (esc ? " Caminhão escolhido pelo Ravi: " + esc.motivo + "." : "")
      + (rotaTar ? "" : " ATENCAO: a rota nao foi achada na tabela da JT."),
    criadaPeloRavi: true, pedidoRavi: e.pedidoPor || ""
  };
  return { ok: true, viagem: v, avisos: avisos, escolha: esc ? esc.motivo : "", conferencia: c, rotaTabela: rotaTar, tipo: veic.tipo || "", peso: Math.round(peso * 1000) / 1000, volumes: volumes, carga: carga, rota: p.rota };
}

